from typing import Tuple, List
from collections import defaultdict

def solve_math_problem(roots: Tuple[int, ...], power: int, target_sum_indices: int) -> int:
    """
    Calculates the sum of coefficients a_k for even k in the polynomial 
    product of (x + r)^power for all r in roots.
    """
    if not roots or power < 0:
        return 0

    # Polynomial representation as a dictionary {exponent: coefficient}
    # Start with the polynomial 1 (x^0)
    poly: dict[int, int] = {0: 1}

    for root in roots:
        for _ in range(power):
            new_poly: dict[int, int] = defaultdict(int)
            # Multiply current poly by (x + root)
            for exp, coeff in poly.items():
                # x * poly
                new_poly[exp + 1] += coeff
                # root * poly
                new_poly[exp] += coeff * root
            poly = dict(new_poly)

    total_sum = 0
    for k in range(0, target_sum_indices + 1, 2):
        total_sum += poly.get(k, 0)

    return total_sum

if __name__ == "__main__":
    assert solve_math_problem((1, 2, 3), 3, 8) == 6696
    assert solve_math_problem((1, 2), 2, 4) == 14

from typing import List, Optional, Set

def solve_math_problem(n: int) -> Optional[int]:
    """
    Finds a Hamiltonian path in a graph where edges exist between numbers 
    i and j if i + j is a perfect square. Returns the sum of the first 
    and last elements of the path.
    """
    squares: Set[int] = {i * i for i in range(2, 2 * n)}
    adj: List[List[int]] = [[] for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i != j and (i + j) in squares:
                adj[i].append(j)

    def find_path(current: int, visited: int, path: List[int]) -> Optional[List[int]]:
        if len(path) == n:
            return path

        for neighbor in adj[current]:
            if not (visited & (1 << neighbor)):
                result = find_path(neighbor, visited | (1 << neighbor), path + [neighbor])
                if result:
                    return result
        return None

    for start_node in range(1, n + 1):
        path = find_path(start_node, 1 << start_node, [start_node])
        if path:
            return path[0] + path[-1]

    return None

